function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // stick figure
  let x = W / 2;
  let y = H / 2;
  let headRadius = 20;
  let bodyLength = 50;
  let armLength = 30;
  let legLength = 40;

  // falling and getting up motion
  let fall = Math.sin(t);
  let getUp = Math.sin(t + Math.PI);

  // head
  ctx.beginPath();
  ctx.arc(x, y - bodyLength / 2 + fall * 10, headRadius, 0, 2 * Math.PI);
  ctx.stroke();

  // body
  ctx.beginPath();
  ctx.moveTo(x, y - bodyLength / 2 + fall * 10 + headRadius);
  ctx.lineTo(x, y - bodyLength / 2 + fall * 10 + headRadius + bodyLength * getUp);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(x, y - bodyLength / 2 + fall * 10 + headRadius + bodyLength * getUp / 2);
  ctx.lineTo(x - armLength, y - bodyLength / 2 + fall * 10 + headRadius + bodyLength * getUp / 2);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(x, y - bodyLength / 2 + fall * 10 + headRadius + bodyLength * getUp / 2);
  ctx.lineTo(x + armLength, y - bodyLength / 2 + fall * 10 + headRadius + bodyLength * getUp / 2);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(x, y - bodyLength / 2 + fall * 10 + headRadius + bodyLength * getUp);
  ctx.lineTo(x - legLength / 2, y - bodyLength / 2 + fall * 10 + headRadius + bodyLength * getUp + legLength * getUp);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(x, y - bodyLength / 2 + fall * 10 + headRadius + bodyLength * getUp);
  ctx.lineTo(x + legLength / 2, y - bodyLength / 2 + fall * 10 + headRadius + bodyLength * getUp + legLength * getUp);
  ctx.stroke();

  ctx.restore();
}
